// O Rubeus manda Content-Type: application/x-www-form-urlencoded, mas o corpo é JSON puro.
// Sem '=' ou '&' no texto, o parser de formulário do n8n transforma o JSON inteiro numa
// única chave com valor vazio. Aqui detectamos esse caso e fazemos o parse manual.

let raw = $json.body;

if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
  const keys = Object.keys(raw);
  if (keys.length === 1 && keys[0].trim().startsWith('{')) {
    raw = keys[0]; // veio como chave por causa do bug do form-urlencoded
  }
}

const data = typeof raw === 'string' ? JSON.parse(raw) : (raw ?? {});

const contatos = data.contatos ?? [];
const contatoPrincipal = contatos.find(c => c.principal === '1') ?? contatos[0] ?? {};

return [{
  json: {
    registro_processo_id: data.id ?? null,
    processo_id: data.processo?.id ?? null,
    processo_nome: data.processo?.nome ?? null,
    etapa_atual: data.resumoAtual?.nome ?? null,
    status: data.status ?? null,
    contato_id: contatoPrincipal.id ?? null,
    contato_tipo: contatoPrincipal.tipo ?? null,
    contato_codigo: contatoPrincipal.codigo ?? null,
    curso_id: data.cursos?.[0]?.id ?? null,
    curso_codigo: data.cursos?.[0]?.codCurso ?? null,
    origem: data.origem?.nome ?? null,
    modalidade: data.modalidade?.nome ?? null,
    unidade: data.unidade?.nome ?? null,
    responsavel_comercial: data.responsavel?.nome ?? null,
    criacao: data.criacao ?? null,
    ultima_alteracao_status: data.ultimaAlteracaoStatus ?? null,
    campos_personalizados: data.camposPersonalizados ?? {},
    raw: data
  }
}];

// A resposta de /api/Contato/dadosPessoa vem em { success, dados: {...} }.
// O Rubeus não retorna Content-Type application/json, então o n8n guarda o corpo
// como TEXTO dentro de $json.data — precisamos fazer o parse manual primeiro.
// camposPersonalizados é um ARRAY de objetos { nome, coluna, tipo, valor } — não um objeto direto.

const processo = $('Normalizar Payload').item.json;
let body = $json;

if (typeof body.data === 'string') {
  try { body = JSON.parse(body.data); } catch (e) { /* mantém body original se falhar */ }
}

const contato = body.dados ?? body;

const camposArray = Array.isArray(contato.camposPersonalizados) ? contato.camposPersonalizados : [];
const gclidCampo = camposArray.find(c =>
  (c.coluna ?? '').toLowerCase().includes('gclid') || (c.nome ?? '').toLowerCase().includes('gclid')
);

return [{
  json: {
    ...processo,
    contato_nome: contato.nome ?? null,
    contato_email: contato.emails?.principal?.email ?? null,
    contato_telefone: contato.telefones?.principal?.telefone ?? null,
    gclid: gclidCampo?.valor ?? null,
    campos_personalizados_contato: camposArray,
    consultado_em: new Date().toISOString()
  }
}];
